jsonTools.init:
function init(eli) {
  // ── Helpers ─────────────────────────────────────────────────────────
  function _section(panel, title) {
    var h = document.createElement("div");
    h.className = "_eli3_settings_section_head";
    h.textContent = title;
    panel.appendChild(h);
    var box = document.createElement("div");
    box.className = "_eli3_settings_section_body";
    panel.appendChild(box);
    return box;
  }
  function _row(label, control, hint) {
    var r = document.createElement("div");
    r.className = "_eli3_settings_row";
    var l = document.createElement("div");
    l.className = "_eli3_settings_label";
    l.textContent = label;
    r.appendChild(l);
    var c = document.createElement("div");
    c.className = "_eli3_settings_control";
    if (control) c.appendChild(control);
    if (hint) {
      var h = document.createElement("div");
      h.className = "_eli3_settings_hint";
      h.textContent = hint;
      c.appendChild(h);
    }
    r.appendChild(c);
    return r;
  }
  function _toggle(checked, onchange, labelText) {
    var wrap = document.createElement("label");
    wrap.className = "_eli3_settings_toggle";
    var cb = document.createElement("input");
    cb.type = "checkbox";
    cb.checked = !!checked;
    cb.onchange = function () { onchange(cb.checked); };
    wrap.appendChild(cb);
    var slider = document.createElement("span");
    slider.className = "_eli3_settings_toggle_slider";
    wrap.appendChild(slider);
    if (labelText) {
      var t = document.createElement("span");
      t.className = "_eli3_settings_toggle_label";
      t.textContent = labelText;
      wrap.appendChild(t);
    }
    return wrap;
  }
  function _readUserSettings() {
    try {
      var raw = eli.compat.lsGet("eli_user_settings");
      return raw ? JSON.parse(raw) : {};
    } catch (e) { return {}; }
  }
  function _writeUserSettings(s) {
    try { eli.compat.lsSet("eli_user_settings", JSON.stringify(s)); }
    catch (e) { /* noop */ }
  }

  // ── Shared section builders (used by Global + Interface) ──────────

  // AI Model selector + inline Edit panel (matches v2 lines 5258-5269).
  // Edit panel lets the user add custom model names (saved as a JSON
  // array in localStorage `eli_custom_models`) that prepend to the
  // built-in list.
  var BUILTIN_MODELS = [
    "gemini-3.1-flash-lite-preview",
    "gemini-2.5-flash",
    "gemini-2.5-pro",
    "gemini-2.0-flash",
  ];
  function _readCustomModels() {
    try {
      var raw = eli.compat.lsGet("eli_custom_models");
      var arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr : [];
    } catch (e) { return []; }
  }
  function _writeCustomModels(arr) {
    try { eli.compat.lsSet("eli_custom_models", JSON.stringify(arr || [])); }
    catch (e) {}
  }
  function _allModels() {
    var custom = _readCustomModels();
    var current = eli.ai.getModel();
    var seen = {};
    var out = [];
    custom.concat(BUILTIN_MODELS).concat([current]).forEach(function (m) {
      if (m && !seen[m]) { seen[m] = true; out.push(m); }
    });
    return out;
  }
  function _inlineRow(controlEl, btnEl) {
    var r = document.createElement("div");
    r.className = "_eli3_settings_inline_row";
    if (controlEl) r.appendChild(controlEl);
    if (btnEl) r.appendChild(btnEl);
    return r;
  }

  function _buildAiModelSection(panel) {
    var box = _section(panel, "🤖 AI Model");
    var modelSel = document.createElement("select");
    modelSel.className = "_eli3_input";
    function _populate() {
      modelSel.innerHTML = "";
      var current = eli.ai.getModel();
      _allModels().forEach(function (m) {
        var o = document.createElement("option");
        o.value = m; o.textContent = m;
        if (m === current) o.selected = true;
        modelSel.appendChild(o);
      });
    }
    _populate();
    modelSel.onchange = function () {
      eli.ai.setModel(modelSel.value);
      showToast("Model: " + modelSel.value, "ok");
    };
    var editToggle = document.createElement("button");
    editToggle.type = "button";
    editToggle.className = "_eli3_settings_link_btn";
    editToggle.textContent = "✏️ Edit";
    box.appendChild(_inlineRow(modelSel, editToggle));

    var editPanel = document.createElement("div");
    editPanel.className = "_eli3_settings_inline_panel";
    editPanel.style.display = "none";
    var editList = document.createElement("div");
    editPanel.appendChild(editList);
    var addInput = document.createElement("input");
    addInput.type = "text";
    addInput.className = "_eli3_input";
    addInput.placeholder = "e.g. gemini-2.5-pro-preview";
    var addBtn = eliButton({
      label: "+ Add",
      onclick: function () {
        var name = (addInput.value || "").trim();
        if (!name) return;
        var custom = _readCustomModels();
        if (custom.indexOf(name) !== -1) { showToast("Already in list.", "warn"); return; }
        custom.push(name);
        _writeCustomModels(custom);
        addInput.value = "";
        _renderEditList();
        _populate();
      },
    });
    editPanel.appendChild(_inlineRow(addInput, addBtn));
    box.appendChild(editPanel);

    function _renderEditList() {
      editList.innerHTML = "";
      var custom = _readCustomModels();
      if (!custom.length) {
        var hint = document.createElement("div");
        hint.className = "_eli3_settings_hint";
        hint.textContent = "Built-ins: " + BUILTIN_MODELS.join(", ");
        editList.appendChild(hint);
        return;
      }
      custom.forEach(function (m, i) {
        var row = document.createElement("div");
        row.className = "_eli3_settings_chip_row";
        var name = document.createElement("span");
        name.textContent = m;
        var delBtn = document.createElement("button");
        delBtn.className = "_eli3_settings_chip_del";
        delBtn.textContent = "✕";
        delBtn.onclick = function () {
          var arr = _readCustomModels();
          arr.splice(i, 1);
          _writeCustomModels(arr);
          _renderEditList();
          _populate();
        };
        row.appendChild(name);
        row.appendChild(delBtn);
        editList.appendChild(row);
      });
    }
    editToggle.onclick = function () {
      var open = editPanel.style.display !== "none";
      editPanel.style.display = open ? "none" : "block";
      editToggle.textContent = open ? "✏️ Edit" : "✕ Done";
      if (!open) _renderEditList();
    };
  }

  function _buildUpdateCheckFreqSection(panel) {
    var box = _section(panel, "🔄 Update-Check Frequency");
    var input = document.createElement("input");
    input.type = "number";
    input.className = "_eli3_input _eli3_settings_input_short";
    input.min = "1"; input.max = "99"; input.step = "1";
    input.value = eli.compat.lsGet("eli_update_check_hours") || "6";
    var suffix = document.createElement("span");
    suffix.className = "_eli3_settings_inline_suffix";
    suffix.textContent = "hours";
    var saveBtn = eliButton({
      label: "Save",
      onclick: function () {
        var n = Math.max(1, Math.min(99, parseInt(input.value, 10) || 6));
        eli.compat.lsSet("eli_update_check_hours", String(n));
        input.value = n;
        showToast("Auto-check every " + n + "h.", "ok");
      },
    });
    var row = document.createElement("div");
    row.className = "_eli3_settings_inline_row";
    row.appendChild(input);
    row.appendChild(suffix);
    row.appendChild(saveBtn);
    box.appendChild(row);
  }

  function _buildLanguageSection(panel) {
    var box = _section(panel, "🌐 Language");
    var sel = document.createElement("select");
    sel.className = "_eli3_input";
    var LANGS = [
      ["en", "English"], ["es", "Español"], ["fr", "Français"],
      ["de", "Deutsch"], ["it", "Italiano"], ["pt", "Português"],
      ["zh", "中文"], ["ja", "日本語"], ["ru", "Русский"],
    ];
    var current = eli.compat.lsGet("eli_language") || "en";
    LANGS.forEach(function (pair) {
      var o = document.createElement("option");
      o.value = pair[0]; o.textContent = pair[1];
      if (pair[0] === current) o.selected = true;
      sel.appendChild(o);
    });
    sel.onchange = function () {
      eli.compat.lsSet("eli_language", sel.value);
      showToast("Language: " + sel.value, "ok");
    };
    box.appendChild(sel);
  }

  // ── Card 1: 🌍 Global ───────────────────────────────────────────────
  function _buildGlobalDetail(panel) {
    _buildCredentialsSection(panel);
    _buildAiModelSection(panel);
    _buildUpdateCheckFreqSection(panel);
    _buildLanguageSection(panel);
    _buildManualInstallSection(panel);
  }

  // 🔐 Keys & Credentials — collapsible. Saved values show as masked
  // (populated state). Admin password gates reveal via eye toggle.
  // FROM v2 lines 5137-5215.
  function _buildCredentialsSection(panel) {
    var wrap = document.createElement("div");
    wrap.className = "_eli3_settings_creds";
    var head = document.createElement("div");
    head.className = "_eli3_settings_creds_head";
    head.innerHTML =
      '<span class="_eli3_settings_creds_caret">▶</span>' +
      '<span class="_eli3_settings_creds_title">🔐 Keys &amp; Credentials</span>' +
      '<span class="_eli3_settings_creds_status" id="_eli3_creds_status"></span>';
    var body = document.createElement("div");
    body.className = "_eli3_settings_creds_body";
    body.style.display = "none";
    head.onclick = function () {
      var open = body.style.display !== "none";
      body.style.display = open ? "none" : "block";
      head.querySelector("._eli3_settings_creds_caret").textContent = open ? "▶" : "▼";
    };
    wrap.appendChild(head);
    wrap.appendChild(body);
    panel.appendChild(wrap);

    var importBtn = eliButton({
      label: "📥 Import credentials bundle",
      onclick: function () { eli.settings.importToken({ title: "Import Credentials" }); },
    });
    importBtn.classList.add("_eli3_settings_cred_import");
    body.appendChild(importBtn);

    // _adminUnlock: shared password gate. Built directly on showEliDialog
    // (the single dialog primitive every other dialog uses) with an inline
    // <input type="password"> so chars are always masked, regardless of
    // kernel version. Returns Promise<bool>. Used by Save gating + eye reveal.
    function _adminUnlock(message) {
      return new Promise(function (resolve) {
        var stored = "";
        try { stored = eli.compat.lsGet("eli_admin_password") || ""; } catch (e) {}
        if (!stored) { resolve(true); return; }
        var inputId = "_eli3_admin_pw_" + Math.random().toString(36).slice(2, 8);
        var errId = inputId + "_err";
        showEliDialog({
          variant: "warning",
          tier: "premium",
          icon: "🔒",
          title: "Admin password required",
          body:
            '<div style="margin-bottom:10px">' + (message || "Enter admin password to continue.") + '</div>' +
            '<input id="' + inputId + '" type="password" class="_eli3_input" />' +
            '<div id="' + errId + '" style="color:#c0392b;font-size:11px;margin-top:6px;display:none"></div>',
          primary: {
            label: "Unlock",
            onclick: function (e, ov) {
              var inp = ov.querySelector("#" + inputId);
              var v = inp ? inp.value : "";
              if (v !== stored) {
                var er = ov.querySelector("#" + errId);
                if (er) { er.textContent = "Wrong password."; er.style.display = "block"; }
                if (inp) inp.value = "";
                return false;
              }
              resolve(true);
            },
          },
          secondary: { label: "Cancel", onclick: function () { resolve(false); } },
          onMount: function (ov) {
            setTimeout(function () {
              var i = ov.querySelector("#" + inputId);
              if (i && i.focus) i.focus();
              if (i) {
                i.addEventListener("keydown", function (e) {
                  if (e.key === "Enter") {
                    var btn = ov.querySelector(".eli-dialog-actions button");
                    if (btn) btn.click();
                  }
                });
              }
            }, 50);
          },
          onClose: function () { resolve(false); },
        });
      });
    }

    function _credRow(opts) {
      // opts: {label, accent, getter, setter, hasValue, isSecret, placeholder, isApi}
      var r = document.createElement("div");
      r.className = "_eli3_settings_cred_row";
      var lbl = document.createElement("div");
      lbl.className = "_eli3_settings_cred_label";
      lbl.style.color = opts.accent;
      lbl.textContent = opts.label;
      r.appendChild(lbl);
      var line = document.createElement("div");
      line.className = "_eli3_settings_cred_line";
      var input = document.createElement("input");
      input.type = opts.isSecret ? "password" : "text";
      input.className = "_eli3_input _eli3_settings_cred_input";
      var saved = !!opts.hasValue();
      if (saved && !opts.isSecret) {
        // Non-secret (e.g. branch): show the actual stored value.
        input.value = opts.getter() || "";
        input.placeholder = opts.placeholder || "";
      } else {
        input.placeholder = saved ? "•••••••••••••••• (set)" : (opts.placeholder || "");
      }
      line.appendChild(input);
      if (opts.isSecret) {
        var eye = document.createElement("button");
        eye.className = "_eli3_settings_cred_eye";
        eye.type = "button";
        eye.title = "Reveal (admin password required)";
        eye.textContent = "👁";
        eye.onclick = function () {
          if (input.value && input.type === "text") {
            input.type = "password"; eye.textContent = "👁"; return;
          }
          _adminUnlock().then(function (ok) {
            if (!ok) return;
            input.value = opts.getter() || "";
            input.type = "text";
            eye.textContent = "🙈";
          });
        };
        line.appendChild(eye);
      }
      var save = eliButton({
        label: "Save",
        onclick: function () {
          // Prompt admin password BEFORE doing anything (incl. validation).
          // The admin-password row itself is the gate-keeper, so ungated.
          function _commit() {
            var v = (input.value || "").trim();
            if (!v) { showToast("Empty value.", "warn"); return; }
            opts.setter(v);
            if (opts.isSecret) {
              input.value = "";
              input.type = "password";
              input.placeholder = "•••••••••••••••• (set)";
            } else {
              input.value = v;
            }
            showToast(opts.label + " saved.", "ok");
            _refreshStatus();
          }
          // Admin gate applies only to secret rows (locked credentials).
          // Branch + admin password are exempt.
          if (opts.isAdminPassword || !opts.isSecret) { _commit(); return; }
          _adminUnlock("Enter admin password to change " + opts.label + ".")
            .then(function (ok) { if (ok) _commit(); });
        },
      });
      save.classList.add("_eli3_settings_cred_save");
      line.appendChild(save);
      r.appendChild(line);
      body.appendChild(r);
    }

    function _ls(key) {
      return {
        getter: function () { try { return eli.compat.lsGet(key) || ""; } catch (e) { return ""; } },
        setter: function (v) { try { eli.compat.lsSet(key, v); } catch (e) {} },
        hasValue: function () { try { return !!eli.compat.lsGet(key); } catch (e) { return false; } },
      };
    }

    // 🔑 API key uses eli.ai (encrypted envelope) — getter unsupported, save only.
    _credRow({
      label: "🔑 Gemini API Key", accent: "#c62828", isSecret: true,
      placeholder: "Paste Gemini API key",
      getter: function () { return ""; },
      setter: function (v) {
        if (v.length < 10) { showToast("Invalid key.", "warn"); return; }
        eli.ai.setApiKey(v);
        if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
      },
      hasValue: function () { return !!eli.ai.hasApiKey(); },
    });
    var lib = _ls("eli_lib_cipher");
    _credRow(Object.assign({label:"📦 Library Cipher", accent:"#7c2d12", isSecret:true, placeholder:"Library cipher"}, lib));
    var pat = _ls("eli_user_github_pat");
    _credRow(Object.assign({label:"🔑 GitHub PAT", accent:"#0f766e", isSecret:true, placeholder:"github_pat_..."}, pat));
    var repo = _ls("eli_github_repo");
    _credRow(Object.assign({label:"📂 GitHub Repo", accent:"#0d47a1", isSecret:true, placeholder:"owner/repo"}, repo));
    var branch = _ls("eli_github_branch");
    _credRow(Object.assign({label:"🌿 GitHub Branch", accent:"#15803d", isSecret:false, placeholder:"main"}, branch));
    var pw = _ls("eli_admin_password");
    _credRow(Object.assign({label:"🔒 Admin Password", accent:"#7e22ce", isSecret:true, placeholder:"Admin password", isAdminPassword:true}, pw));

    function _refreshStatus() {
      var keys = ["eli_lib_cipher","eli_user_github_pat","eli_github_repo","eli_github_branch","eli_admin_password"];
      var setCount = keys.filter(function (k) { try { return !!eli.compat.lsGet(k); } catch (e) { return false; } }).length;
      if (eli.ai.hasApiKey()) setCount++;
      var el = wrap.querySelector("#_eli3_creds_status");
      if (el) el.textContent = setCount + " / 6 set";
    }
    _refreshStatus();
  }

  // ── Card 2: ✨ Interface ────────────────────────────────────────────
  function _buildInterfaceDetail(panel) {
    // Theme (FROM v2 lines 5283-5286 + headerTheme cycle logic).
    var themeBox = _section(panel, "Header Theme");
    var THEMES = [
      "Default", "Classic White", "Executive", "Midnight", "Oceanic",
      "Emerald", "Royal", "Copper", "Minimalist",
    ];
    var settings = _readUserSettings();
    var themeSel = document.createElement("select");
    themeSel.className = "_eli3_input";
    THEMES.forEach(function (t, i) {
      var o = document.createElement("option");
      o.value = String(i); o.textContent = t;
      if ((settings.headerThemeIndex || 0) === i) o.selected = true;
      themeSel.appendChild(o);
    });
    themeSel.onchange = function () {
      var s = _readUserSettings();
      s.headerThemeIndex = parseInt(themeSel.value, 10) || 0;
      _writeUserSettings(s);
      if (eli.dashboard) eli.dashboard.refresh();
      var header = document.querySelector(".header");
      if (header) {
        ["theme-classic-white","theme-executive","theme-midnight","theme-oceanic",
         "theme-emerald","theme-royal","theme-copper","theme-minimalist"].forEach(function (c) {
          header.classList.remove(c);
        });
        var classes = ["","theme-classic-white","theme-executive","theme-midnight",
          "theme-oceanic","theme-emerald","theme-royal","theme-copper","theme-minimalist"];
        var cls = classes[s.headerThemeIndex];
        if (cls) header.classList.add(cls);
      }
    };
    themeBox.appendChild(themeSel);

    // Behaviors (FROM v2 lines 5279-5306) — Light Mode + 4 toggles +
    // Debug Mode. Each writes a key on the `eli_user_settings` blob to
    // match v2 storage so v2/v3 don't fight.
    var behaviorBox = _section(panel, "Behaviors");
    function _toggleSetting(key, defaultVal, label, hint) {
      var s = _readUserSettings();
      var initial = (s[key] === undefined) ? defaultVal : !!s[key];
      var t = _toggle(initial, function (v) {
        var cur = _readUserSettings();
        cur[key] = v;
        _writeUserSettings(cur);
      });
      behaviorBox.appendChild(_row(label, t, hint));
    }
    _toggleSetting("lightMode", false, "☀️ Light Mode",
      "Switches the taskpane to a light palette. Affects current session — refresh to apply across all paint paths.");
    // Bind the lightMode toggle's behavior to also flip the body class.
    // (We re-create with side effect since _toggleSetting wraps a generic toggle.)
    behaviorBox.lastChild.querySelector("input").addEventListener("change", function (e) {
      if (e.target.checked) document.body.classList.add("light-mode");
      else document.body.classList.remove("light-mode");
    });
    _toggleSetting("aiSpeechBubbles", true, "💬 AI Speech Bubbles",
      "Show ELI's commentary as speech bubbles in tool dialogs. Off = silent UI.");
    _toggleSetting("minimizeFeed", false, "📌 Minimize Session Feed on Start",
      "Start the dashboard with the session feed collapsed.");
    _toggleSetting("autoHideSidebar", false, "📊 Auto-Hide Sidebar (Stats Panel)",
      "Hide the stats sidebar by default; re-show via the toggle in the dashboard.");
    _toggleSetting("autoExpandWindow", false, "↔️ Auto-Expand Taskpane on Load",
      "Office.js expands the taskpane width on every reload. Off = honor the user's last-set width.");

    // Debug + capture toggles — moved here from the (deferred) Data Hub
    // card. Belong on Interface per v2 layout (v2 line 5304 has the
    // Debug Mode toggle in setGroupView).
    _buildDebugSection(panel);

    // Reset View / Reset All (FROM v2 lines 5307 + 5310-5312).
    var resetBox = _section(panel, "Reset");
    var resetRow = document.createElement("div");
    resetRow.style.cssText = "display:flex;gap:8px;flex-wrap:wrap";
    resetRow.appendChild(eliButton({
      label: "↺ Reset View",
      variant: "secondary",
      onclick: function () {
        eli.ui.confirm({
          title: "Reset view settings?",
          message: "Resets theme, light mode, sidebar, feed, and behavior toggles. API key and tools are not touched.",
        }).then(function (ok) {
          if (!ok) return;
          var s = _readUserSettings();
          delete s.headerThemeIndex; delete s.lightMode;
          delete s.aiSpeechBubbles; delete s.minimizeFeed;
          delete s.autoHideSidebar; delete s.autoExpandWindow;
          _writeUserSettings(s);
          document.body.classList.remove("light-mode");
          if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
          showToast("View reset.", "ok");
        });
      },
    }));
    resetRow.appendChild(eliButton({
      label: "⚠️ Reset All",
      variant: "danger",
      onclick: function () {
        eli.ui.confirm({
          title: "Reset everything?",
          message: "Clears local user settings, debug flag, and zoom level. API key, encrypted credentials, and installed tools are NOT touched. Reload after.",
        }).then(function (ok) {
          if (!ok) return;
          try { eli.compat.lsRemove("eli_user_settings"); } catch (e) {}
          try { eli.compat.lsRemove("_eli3_zoom"); } catch (e) {}
          try { eli.compat.lsRemove("eli_rawBlocked"); } catch (e) {}
          try { eli.debug(false); } catch (e) {}
          document.body.classList.remove("light-mode");
          if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
          showToast("All view + debug settings reset.", "ok");
        });
      },
    }));
    resetBox.appendChild(resetRow);
  }

  // ── Card 3: 🗄️ Data Hub (deferred — v2 feature not yet migrated) ────
  // v2's Data Hub is a full-page view (showDataHub at v2 line 13341):
  // import/export master JSON, per-section management, etc. Until that
  // migrates, this card is a stub. The settings that USED to live here
  // (per-tool toggles, manifest URL, manual install, debug toggles)
  // moved to Global / Interface to match v2's layout.
  function _buildDataHubDetail(panel) {
    var box = document.createElement("div");
    box.className = "_eli3_settings_hint";
    box.style.cssText = "padding:24px 16px;text-align:center;font-size:13px;line-height:1.6";
    box.innerHTML =
      '<div style="font-size:32px;margin-bottom:10px">🗄️</div>' +
      '<b>Data Hub hasn\'t migrated to v3 yet.</b><br>' +
      '<span style="color:#94a3b8">' +
        'In v2 this opens a full-page view for import/export of the master ' +
        'JSON and per-section management. It will return when the feature ' +
        'ports over.' +
      '</span>' +
      '<div style="margin-top:14px;font-size:12px;color:#475569;text-align:left;display:inline-block;background:#f1f5f9;padding:10px 14px;border-radius:6px">' +
        '<b>Looking for these?</b><br>' +
        '• Per-tool on/off toggles → <b>Global</b><br>' +
        '• Manifest URL + manual install → <b>Global</b><br>' +
        '• Debug logging + wrongness capture → <b>Interface</b>' +
      '</div>';
    panel.appendChild(box);
  }

  // Split out of the old _buildAdvancedSection — Wrongness Capture +
  // Debug Logging now live on the Interface card (not Data Hub).
  function _buildDebugSection(panel) {
    var capBox = _section(panel, "Wrongness Capture");
    capBox.appendChild(_row(
      "Capture engine runs",
      _toggle(eli.wrongness.isEnabled(), function (v) {
        eli.wrongness.setEnabled(v);
        showToast(v ? "Capture on" : "Capture off", "ok");
      }),
      "Engine inputs/outputs are stored (sanitized — no doc text) so you can replay and report bugs. Capped at " + eli.wrongness.MAX_CAPTURES + " entries."
    ));

    var dbgBox = _section(panel, "Debug Logging");
    dbgBox.appendChild(_row(
      "Verbose console logs",
      _toggle(!!eli.debug(), function (v) {
        eli.debug(v);
        showToast(v ? "Debug on" : "Debug off", "ok");
      }),
      "Off by default. Turn on when reproducing a bug for the developer."
    ));
  }

  // Split out of the old _buildAdvancedSection — Tool Updates + Manifest
  // URL now live on the Global card (admin/connectivity).
  function _buildToolUpdatesSection(panel) {
    var syncBox = _section(panel, "Tool Updates");
    var lastCheckTs = parseFloat(eli.compat.lsGet("eli_lastUpdateCheck")) || 0;
    var lastCheckEl = document.createElement("div");
    lastCheckEl.className = "_eli3_settings_hint";
    lastCheckEl.id = "_eli3_settings_lastcheck";
    function _formatLastCheck(ts) {
      if (!ts) return "Never checked.";
      var d = new Date(ts);
      var sec = Math.floor((Date.now() - ts) / 1000);
      var rel = sec < 60 ? "just now"
        : sec < 3600 ? Math.floor(sec / 60) + "m ago"
        : sec < 86400 ? Math.floor(sec / 3600) + "h ago"
        : Math.floor(sec / 86400) + "d ago";
      return "Last checked: " + d.toLocaleString() + " (" + rel + ")";
    }
    lastCheckEl.textContent = _formatLastCheck(lastCheckTs);
    syncBox.appendChild(lastCheckEl);
    var checkBtn = eliButton({
      label: "🔄 Check for updates now",
      onclick: function () {
        var origLabel = checkBtn.textContent;
        checkBtn.textContent = "⏳ Checking…";
        checkBtn.disabled = true;
        var detailEl = document.getElementById("_eli3_settings_check_detail");
        if (detailEl) detailEl.innerHTML = "";
        showToast("Checking…", "ok");
        eli.tools.syncFromManifest({ force: true }).then(function (sync) {
          var msg, inline;
          if (sync.installed && sync.updates && sync.updates.length) {
            msg = "Installed " + sync.installed + ", " + sync.updates.length + " update" + (sync.updates.length === 1 ? "" : "s") + " pending";
            inline = "✓ " + sync.installed + " new, " + sync.updates.length + " update" + (sync.updates.length === 1 ? "" : "s");
          } else if (sync.installed) {
            msg = "Installed " + sync.installed + " new bundle" + (sync.installed === 1 ? "" : "s");
            inline = "✓ Installed " + sync.installed;
          } else if (sync.updates && sync.updates.length) {
            msg = sync.updates.length + " update" + (sync.updates.length === 1 ? "" : "s") + " available — see footer";
            inline = "✓ " + sync.updates.length + " update" + (sync.updates.length === 1 ? "" : "s") + " available";
          } else {
            msg = "Already up to date";
            inline = "✓ Up to date";
          }
          showToast(msg, "ok");
          checkBtn.textContent = inline;
          setTimeout(function () { checkBtn.textContent = origLabel; checkBtn.disabled = false; }, 2500);
          var lc = document.getElementById("_eli3_settings_lastcheck");
          if (lc) lc.textContent = _formatLastCheck(Date.now());
          _renderCheckDetail(sync);
        }).catch(function (err) {
          showToast("Check failed: " + (err && err.message || "unknown"), "err");
          checkBtn.textContent = "✗ Check failed";
          setTimeout(function () { checkBtn.textContent = origLabel; checkBtn.disabled = false; }, 2500);
          _renderCheckDetail({ error: err });
        });
      },
    });
    var checkWrap = document.createElement("div");
    checkWrap.style.marginTop = "8px";
    checkWrap.appendChild(checkBtn);
    syncBox.appendChild(checkWrap);
    var detailWrap = document.createElement("div");
    detailWrap.id = "_eli3_settings_check_detail";
    detailWrap.className = "_eli3_settings_check_detail";
    syncBox.appendChild(detailWrap);
    function _renderCheckDetail(sync) {
      var wrap = document.getElementById("_eli3_settings_check_detail");
      if (!wrap) return;
      if (sync.error) {
        wrap.innerHTML = '<div class="_eli3_settings_check_err">⚠️ ' + String(sync.error.message || sync.error) + '</div>';
        return;
      }
      Promise.all([eli.tools.list(), eli.tools.getCachedManifest()]).then(function (r) {
        var installed = r[0] || [];
        var manifest = r[1];
        var installedMap = {};
        installed.forEach(function (t) { installedMap[t.id] = t; });
        var rawBlocked = eli.compat.lsGet("eli_rawBlocked") === "1";
        var customUrl = eli.compat.lsGet("eli_manifest_url");
        var rows = (manifest && manifest.tools || []).map(function (entry) {
          var local = installedMap[entry.id];
          var rTs = entry.lastUpdated || entry.releasedAt || "—";
          var lTs = local ? (local.releasedAt || (local.installedAt ? new Date(local.installedAt).toISOString() : "—")) : "(not installed)";
          var verdict;
          if (!local) {
            verdict = '<span style="color:#1565c0">install</span>';
          } else {
            try {
              var rD = Date.parse(rTs), lD = Date.parse(lTs);
              if (!isNaN(rD) && !isNaN(lD)) {
                verdict = rD > lD
                  ? '<span style="color:#1565c0">↑ update</span>'
                  : rD < lD
                    ? '<span style="color:#94a3b8">local newer</span>'
                    : '<span style="color:#16a34a">in sync</span>';
              } else {
                verdict = '<span style="color:#94a3b8">no timestamps</span>';
              }
            } catch (e) { verdict = '<span style="color:#94a3b8">?</span>'; }
          }
          return '<tr>' +
            '<td>' + (entry.id || "?") + '</td>' +
            '<td title="' + lTs + '">' + (lTs.length > 19 ? lTs.slice(0, 19) : lTs) + '</td>' +
            '<td title="' + rTs + '">' + (String(rTs).length > 19 ? String(rTs).slice(0, 19) : rTs) + '</td>' +
            '<td>' + verdict + '</td>' +
            '</tr>';
        }).join("");
        var srcLabel = customUrl
          ? "custom URL"
          : rawBlocked
            ? "jsdelivr (raw blocked)"
            : "raw.githubusercontent (with jsdelivr fallback)";
        wrap.innerHTML =
          '<div class="_eli3_settings_check_meta">' +
            '<b>Source:</b> ' + srcLabel +
            ' &nbsp;·&nbsp; <b>Tools:</b> ' + (manifest && manifest.tools ? manifest.tools.length : 0) +
          '</div>' +
          '<table class="_eli3_settings_check_table">' +
            '<thead><tr><th>id</th><th>local</th><th>remote</th><th>verdict</th></tr></thead>' +
            '<tbody>' + rows + '</tbody>' +
          '</table>';
      });
    }

    var hoursWrap = document.createElement("div");
    hoursWrap.style.cssText = "margin-top:10px;display:flex;align-items:center;gap:6px";
    var hoursLabel = document.createElement("span");
    hoursLabel.style.cssText = "font:11px/1.4 system-ui;color:inherit";
    hoursLabel.textContent = "Auto-check every";
    var hoursInput = document.createElement("input");
    hoursInput.type = "number";
    hoursInput.className = "_eli3_input";
    hoursInput.style.cssText = "width:60px;padding:4px 6px";
    hoursInput.min = "1";
    hoursInput.max = "168";
    hoursInput.value = eli.compat.lsGet("eli_update_check_hours") || "6";
    hoursInput.onchange = function () {
      var n = Math.max(1, Math.min(168, parseInt(hoursInput.value, 10) || 6));
      eli.compat.lsSet("eli_update_check_hours", String(n));
      hoursInput.value = n;
      showToast("Saved. Auto-check every " + n + "h.", "ok");
    };
    var hoursSuffix = document.createElement("span");
    hoursSuffix.style.cssText = "font:11px/1.4 system-ui;color:inherit";
    hoursSuffix.textContent = "hours";
    hoursWrap.appendChild(hoursLabel);
    hoursWrap.appendChild(hoursInput);
    hoursWrap.appendChild(hoursSuffix);
    syncBox.appendChild(hoursWrap);

    var manifestBox = _section(panel, "Manifest URL");
    var defaultUrl = (eli.tools && eli.tools.DEFAULT_MANIFEST_URL) || "";
    var current = eli.compat.lsGet("eli_manifest_url") || defaultUrl;
    var urlInput = document.createElement("input");
    urlInput.type = "text";
    urlInput.className = "_eli3_input";
    urlInput.value = current;
    urlInput.style.fontFamily = "monospace";
    urlInput.style.fontSize = "11px";
    var urlBtns = document.createElement("div");
    urlBtns.style.cssText = "display:flex;gap:6px;margin-top:8px";
    urlBtns.appendChild(eliButton({
      label: "Save",
      onclick: function () {
        var v = (urlInput.value || "").trim();
        if (!v) v = defaultUrl;
        if (v === defaultUrl) eli.compat.lsRemove("eli_manifest_url");
        else eli.compat.lsSet("eli_manifest_url", v);
        showToast("Manifest URL saved. Restart to apply.", "ok");
      },
    }));
    urlBtns.appendChild(eliButton({
      label: "Reset to default",
      variant: "secondary",
      onclick: function () {
        eli.compat.lsRemove("eli_manifest_url");
        urlInput.value = defaultUrl;
        showToast("Reset to default.", "ok");
      },
    }));
    manifestBox.appendChild(urlInput);
    manifestBox.appendChild(urlBtns);
    var defHint = document.createElement("div");
    defHint.className = "_eli3_settings_hint";
    defHint.style.marginTop = "8px";
    defHint.innerHTML = "Default: <code>" + defaultUrl + "</code>";
    manifestBox.appendChild(defHint);
  }

  // Split out of the old _buildAdvancedSection — Manual Install now
  // lives on the Global card (bootstrap-recovery / side-load path).
  function _buildManualInstallSection(panel) {
    var manualBox = _section(panel, "Manual Install");
    var manualHint = document.createElement("div");
    manualHint.className = "_eli3_settings_hint";
    manualHint.innerHTML =
      "Install a tool, data bundle, or credentials token from a local " +
      ".json file. Use this when CDN is unreachable or to side-load a " +
      "pre-release build.";
    manualBox.appendChild(manualHint);
    var manualBtn = eliButton({
      label: "📦 Import package…",
      onclick: function () {
        if (eli.settings && eli.settings.importPackage) eli.settings.importPackage();
      },
    });
    var manualWrap = document.createElement("div");
    manualWrap.style.marginTop = "8px";
    manualWrap.appendChild(manualBtn);
    manualBox.appendChild(manualWrap);
  }

  // ── Card 4: 🪄 Draft Templates (stub) ───────────────────────────────
  function _buildDraftTemplatesDetail(panel) {
    var hint = document.createElement("div");
    hint.className = "_eli3_settings_hint";
    hint.style.cssText = "padding:24px 16px;text-align:center;font-size:13px;line-height:1.6";
    hint.innerHTML =
      '<div style="font-size:32px;margin-bottom:10px">🪄</div>' +
      '<b>Draft Templates configuration unlocks once Build Draft migrates to v3.</b><br>' +
      '<span style="color:#94a3b8">Until then, Build Draft uses its v2-bundled templates.</span>';
    panel.appendChild(hint);
  }

  var CARDS = [
    { id: "global",    icon: "🌍", title: "Global",          desc: "API Key, Language, Updates",  build: _buildGlobalDetail },
    { id: "interface", icon: "✨", title: "Interface",       desc: "Themes & Views",              build: _buildInterfaceDetail },
    { id: "datahub",   icon: "🗄️", title: "Data Hub",        desc: "Tools, Prompts, Library",     build: _buildDataHubDetail },
    { id: "drafttpl",  icon: "🪄", title: "Draft Templates", desc: "Build Draft Config",          build: _buildDraftTemplatesDetail },
  ];

  // ── Hub renderer ────────────────────────────────────────────────────
  function _renderHub(host) {
    host.innerHTML = "";
    var grid = document.createElement("div");
    grid.className = "_eli3_cc_grid_view";
    var hdr = document.createElement("div");
    hdr.className = "_eli3_cc_header";
    hdr.innerHTML =
      '<button class="_eli3_cc_back_btn" title="Back to dashboard">←</button>' +
      '<div>' +
        '<div class="_eli3_cc_title">Command Center</div>' +
        '<div class="_eli3_cc_subtitle">System Preferences</div>' +
      '</div>';
    hdr.querySelector("._eli3_cc_back_btn").onclick = function () {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
      else if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
    };
    grid.appendChild(hdr);
    var checkRow = document.createElement("div");
    checkRow.className = "_eli3_cc_check_row";
    var checkBtn = document.createElement("div");
    checkBtn.className = "_eli3_cc_toggle_btn";
    checkBtn.textContent = "🔄 Check for updates";
    checkBtn.onclick = function () { _runCheckForUpdates(checkBtn); };
    checkRow.appendChild(checkBtn);
    grid.appendChild(checkRow);
    var cardGrid = document.createElement("div");
    cardGrid.className = "_eli3_cc_card_grid";
    CARDS.forEach(function (card) {
      var el = document.createElement("div");
      el.className = "_eli3_cc_card";
      el.innerHTML =
        '<span class="_eli3_cc_icon">' + card.icon + '</span>' +
        '<div class="_eli3_cc_card_title">' + card.title + '</div>' +
        '<div class="_eli3_cc_desc">' + card.desc + '</div>';
      el.onclick = function () { _renderDetail(host, card); };
      cardGrid.appendChild(el);
    });
    grid.appendChild(cardGrid);
    var footer = document.createElement("div");
    footer.className = "_eli3_cc_footer_row";
    var lightBtn = document.createElement("div");
    lightBtn.className = "_eli3_cc_toggle_btn";
    var settings = _readUserSettings();
    lightBtn.textContent = settings.lightMode ? "🌙 Switch to Dark" : "☀️ Switch to Light";
    lightBtn.onclick = function () {
      var s = _readUserSettings();
      s.lightMode = !s.lightMode;
      _writeUserSettings(s);
      if (s.lightMode) document.body.classList.add("light-mode");
      else document.body.classList.remove("light-mode");
      lightBtn.textContent = s.lightMode ? "🌙 Switch to Dark" : "☀️ Switch to Light";
    };
    var resetBtn = document.createElement("div");
    resetBtn.className = "_eli3_cc_toggle_btn _eli3_cc_reset_btn";
    resetBtn.textContent = "↺ Reset to Default";
    resetBtn.onclick = function () {
      eli.ui.confirm({
        title: "Reset to default?",
        message: "Resets theme, light mode, and zoom. API key and tools are not touched.",
      }).then(function (ok) {
        if (!ok) return;
        var s = _readUserSettings();
        s.headerThemeIndex = 0;
        s.lightMode = false;
        _writeUserSettings(s);
        document.body.classList.remove("light-mode");
        try { eli.compat.lsRemove("_eli3_zoom"); } catch (e) {}
        try { eli.compat.lsRemove("eli_rawBlocked"); } catch (e) {}
        if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
        showToast("Reset to defaults", "ok");
      });
    };
    footer.appendChild(lightBtn);
    footer.appendChild(resetBtn);
    grid.appendChild(footer);
    host.appendChild(grid);
  }

  function _renderDetail(host, card) {
    host.innerHTML = "";
    var view = document.createElement("div");
    view.className = "_eli3_cc_detail_view";
    var bar = document.createElement("div");
    bar.className = "_eli3_cc_detail_bar";
    bar.innerHTML =
      '<button class="_eli3_cc_back_btn">←</button>' +
      '<div class="_eli3_cc_detail_title">' + card.icon + ' ' + card.title + '</div>';
    bar.querySelector("._eli3_cc_back_btn").onclick = function () { _renderHub(host); };
    view.appendChild(bar);
    var content = document.createElement("div");
    content.className = "_eli3_cc_detail_body";
    var card2 = document.createElement("div");
    card2.className = "_eli3_cc_detail_card";
    content.appendChild(card2);
    view.appendChild(content);
    host.appendChild(view);
    try { card.build(card2); }
    catch (e) {
      card2.innerHTML = '<div class="_eli3_settings_check_err">Detail render failed: ' + (e.message || e) + '</div>';
    }
  }

  function _runCheckForUpdates(btn) {
    var origLabel = btn.textContent;
    btn.textContent = "⏳ Checking…";
    btn.style.pointerEvents = "none";
    eli.tools.syncFromManifest({ force: true }).then(function (sync) {
      // Restore the button immediately, then open the v2-style downloads
      // dialog (shows "<email> · Downloads" with per-row checkboxes).
      // Replaces the old footer-button pattern — instant, no hunt.
      btn.textContent = origLabel;
      btn.style.pointerEvents = "";
      if (eli.dashboard && eli.dashboard.showDownloadsDialog) {
        eli.dashboard.showDownloadsDialog(sync);
      } else {
        // Fallback if dashboard.showDownloadsDialog isn't wired (older
        // kernel pre-Phase 10c). Just toast the result.
        var n = (sync && sync.installed) || 0;
        var u = (sync && sync.updates && sync.updates.length) || 0;
        var msg = n > 0 ? "Installed " + n + " new bundle(s)."
          : u > 0 ? u + " update(s) available."
          : "Already up to date.";
        showToast(msg, n > 0 ? "ok" : "info");
      }
    }).catch(function (err) {
      btn.textContent = origLabel;
      btn.style.pointerEvents = "";
      showToast("Check failed: " + (err && err.message || "unknown"), "err");
    });
  }

  // ── show() — public entry point ─────────────────────────────────────
  // Full-area takeover (matches v2's resizable cc-premium-modal + the v3
  // docuscrub pattern). Mount on #_eli3_dashboard_root so the Command
  // Center fills the taskpane and inherits Office.js's natural sizing
  // (vs a fixed-width dialog). On close, eli.dashboard.goHome() rebuilds
  // the dashboard from scratch.
  function show() {
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      // Fallback — shouldn't happen if dashboard rendered, but if the
      // root is missing for some reason, surface a clear error rather
      // than silently no-op.
      if (typeof showToast === "function") {
        showToast("Dashboard root not ready. Reload the taskpane.", "err");
      }
      return;
    }
    // Take over the dashboard area entirely — sidebar + main + footer.
    // The previous dashboard markup is rebuilt on goHome() below.
    mount.innerHTML = "";

    var root = document.createElement("div");
    root.className = "_eli3_cc_root";
    var body = document.createElement("div");
    body.id = "_eli3_cc_body";
    body.className = "_eli3_cc_body_full";
    root.appendChild(body);
    mount.appendChild(root);
    _renderHub(body);
  }

  // Override the kernel's stub. importToken / importPackage / maybeFirstRun
  // stay kernel-side (onboarding + manual install per CLAUDE.md).
  eli.settings.show = show;
  eli.log.event("tool", "eli_settings_initialized", {});
}

jsonTools.css:
/* eli_settings tool styles. Injected by kernel as <style data-tool="eli_settings">. */

/* ─── Command Center skeleton ─────────────────────────────────────── */
._eli3_cc_root {
  display: flex; flex-direction: column; width: 100%; height: 100%;
  min-height: 100%; box-sizing: border-box;
  background: #fff; overflow: hidden;
}
._eli3_cc_body_full { flex: 1 1 auto; overflow-y: auto; width: 100%; }
._eli3_cc_grid_view { padding: 14px 16px 18px; background: #fff; }

._eli3_cc_header {
  display: flex; align-items: center; gap: 10px; margin-bottom: 12px;
  padding-bottom: 10px; border-bottom: 1px solid #e2e8f0;
}
._eli3_cc_back_btn {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #64748b;
  padding: 0 4px; line-height: 1;
}
._eli3_cc_back_btn:hover { color: #1565c0; }
._eli3_cc_title { font: 800 17px/1.2 'Georgia', serif; color: #0f172a; letter-spacing: -0.2px; }
._eli3_cc_subtitle {
  font: 700 9px/1 'Inter', sans-serif; color: #64748b;
  text-transform: uppercase; letter-spacing: 1.2px; margin-top: 3px;
}

._eli3_cc_check_row { text-align: center; margin-bottom: 12px; }
._eli3_cc_toggle_btn {
  display: inline-block; padding: 8px 18px;
  font: 800 11px/1.2 'Inter', sans-serif;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff; border: 1px solid rgba(0,0,0,0.1);
  cursor: pointer; text-transform: uppercase; letter-spacing: 0.5px;
  transition: transform .12s, box-shadow .12s; user-select: none;
}
._eli3_cc_toggle_btn:hover { transform: translateY(-1px); box-shadow: 0 4px 10px rgba(21,101,192,0.3); }

._eli3_cc_card_grid {
  display: grid; grid-template-columns: repeat(2, 1fr);
  gap: 8px; margin-bottom: 14px;
}
._eli3_cc_card {
  background: #fff; border: 1px solid #cbd5e1;
  padding: 14px 10px; display: flex; flex-direction: column;
  align-items: center; text-align: center; cursor: pointer;
  transition: transform .15s, box-shadow .15s, border-color .15s;
  box-shadow: 0 2px 6px rgba(0,0,0,0.03), inset 0 1px 0 rgba(255,255,255,0.6);
}
._eli3_cc_card:hover {
  transform: translateY(-2px); border-color: #3b82f6;
  box-shadow: 0 8px 18px rgba(59,130,246,0.13);
}
._eli3_cc_icon { font-size: 26px; margin-bottom: 4px; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.06)); }
body.light-mode ._eli3_cc_icon { filter: none; }
@media (max-width: 380px) {
  ._eli3_cc_card_grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 320px) {
  ._eli3_cc_icon { display: none; }
}
._eli3_cc_card_title { font: 800 13px/1.2 'Inter', sans-serif; color: #0f172a; }
._eli3_cc_desc {
  font: 600 10px/1.2 'Inter', sans-serif; color: #64748b;
  text-transform: uppercase; letter-spacing: 0.4px; margin-top: 2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%;
}

._eli3_cc_footer_row {
  display: flex; justify-content: space-between; gap: 8px;
  border-top: 1px dashed rgba(100,116,139,0.3); padding-top: 12px;
}
._eli3_cc_footer_row ._eli3_cc_toggle_btn {
  flex: 1; display: flex; align-items: center; justify-content: center;
  gap: 6px; text-align: center;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  border: 1px solid #b0bec5; border-top: 1px solid #cfd8dc;
  box-shadow: inset 0 1px 0 #ffffff, 0 1px 2px rgba(0,0,0,0.08);
  color: #546e7a; font-weight: 700; text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}
._eli3_cc_footer_row ._eli3_cc_toggle_btn:hover {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  border-color: #90caf9; color: #1565c0;
  transform: translateY(-1px);
  box-shadow: inset 0 1px 0 #fff, 0 4px 8px rgba(21,101,192,0.15);
}
._eli3_cc_reset_btn { color: #ef4444 !important; }
._eli3_cc_reset_btn:hover {
  background: linear-gradient(to bottom, #fff5f5 0%, #fee2e2 100%) !important;
  border-color: #ef4444 !important; color: #b91c1c !important;
}

/* ─── Detail view ─────────────────────────────────────────────────── */
._eli3_cc_detail_view { display: flex; flex-direction: column; background: #fff; height: 100%; min-height: 100%; }
._eli3_cc_detail_bar {
  display: flex; align-items: center; padding: 10px 14px;
  border-bottom: 1px solid #e2e8f0; background: #fff; flex-shrink: 0;
}
._eli3_cc_back_btn { background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #64748b; padding: 0 8px 0 0; }
._eli3_cc_back_btn:hover { color: #1565c0; }
._eli3_cc_detail_title { flex: 1; font: 800 14px/1.2 'Inter', sans-serif; color: #0f172a; text-align: center; margin-right: 30px; }
._eli3_cc_detail_body { flex: 1; overflow-y: auto; padding: 18px 0 24px; }
._eli3_cc_detail_card {
  max-width: 75%;
  margin: 0 auto;
  padding: 14px;
  border: 1px solid #cbd5e1;
  background: #fff;
}

/* ─── Section pattern — eyebrow + body, all centered. ────────────── */
._eli3_settings_section_head {
  font: 800 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  color: #0f172a; margin: 12px 0 4px;
  padding-bottom: 4px; border-bottom: 1px solid #e2e8f0;
  text-align: center;
}
._eli3_settings_section_head:first-child { margin-top: 0; }
._eli3_settings_section_body { padding: 4px 0 6px; text-align: center; }

._eli3_settings_row {
  display: flex; justify-content: center; align-items: center;
  gap: 10px; padding: 5px 0;
  border-bottom: 1px solid #f1f5f9;
}
._eli3_settings_row:last-child { border-bottom: none; }
._eli3_settings_label { font: 600 12px/1.3 'Inter', sans-serif; color: #1e293b; }
._eli3_settings_control { display: flex; align-items: center; gap: 6px; }
._eli3_settings_hint { font: 400 11px/1.35 'Inter', sans-serif; color: #64748b; margin-top: 2px; text-align: center; }

/* ─── Inline (input + suffix + button on same line, centered) ─────── */
._eli3_settings_inline_row {
  display: flex; gap: 6px; align-items: center; justify-content: center;
  margin-top: 4px;
}
._eli3_settings_inline_row > ._eli3_input { flex: 1; }
._eli3_input._eli3_settings_input_short { width: 64px !important; flex: 0 0 auto !important; text-align: center; }
._eli3_settings_inline_suffix { font: 600 11px/1.4 'Inter', sans-serif; color: #475569; }
._eli3_settings_link_btn {
  background: none; border: none; cursor: pointer;
  font: 700 11px/1 'Inter', sans-serif; color: #1565c0;
  padding: 4px 6px; flex: 0 0 auto;
}
._eli3_settings_link_btn:hover { text-decoration: underline; }
._eli3_settings_inline_panel {
  margin-top: 6px; padding: 8px 10px;
  background: #f8fafc; border: 1px solid #e2e8f0;
}
._eli3_settings_chip_row {
  display: flex; align-items: center; gap: 8px;
  padding: 4px 0; font: 600 11px/1.3 'JetBrains Mono', monospace;
  color: #0f172a;
}
._eli3_settings_chip_row > span:first-child { flex: 1; }
._eli3_settings_chip_del {
  background: none; border: none; cursor: pointer;
  color: #ef4444; font: 800 12px/1 'Inter', sans-serif;
}

/* ─── Inputs ──────────────────────────────────────────────────────── */
._eli3_input {
  width: 100%; padding: 6px 8px;
  border: 1px solid #cbd5e1; background: #fff;
  font: 12px 'Inter', sans-serif; color: #0f172a;
  box-sizing: border-box;
}
._eli3_input:focus { outline: none; border-color: #1565c0; }

/* ─── Toggle switch ───────────────────────────────────────────────── */
._eli3_settings_toggle { display: inline-flex; align-items: center; gap: 6px; cursor: pointer; user-select: none; }
._eli3_settings_toggle input[type="checkbox"] { position: absolute; opacity: 0; pointer-events: none; }
._eli3_settings_toggle_slider {
  width: 32px; height: 16px; background: #cbd5e1;
  position: relative; transition: background 0.15s; display: inline-block;
}
._eli3_settings_toggle_slider::after {
  content: ""; position: absolute; top: 2px; left: 2px;
  width: 12px; height: 12px; background: #fff; transition: left 0.15s;
}
._eli3_settings_toggle input:checked + ._eli3_settings_toggle_slider { background: #1565c0; }
._eli3_settings_toggle input:checked + ._eli3_settings_toggle_slider::after { left: 18px; }
._eli3_settings_toggle_label { font: 600 12px/1.3 'Inter', sans-serif; color: #1e293b; }

/* ─── Keys & Credentials ──────────────────────────────────────────── */
._eli3_settings_creds { border: 1px solid #cbd5e1; background: #fff; margin: 0 0 12px; }
._eli3_settings_creds_head {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  padding: 9px 12px; cursor: pointer; user-select: none;
  background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%);
  border-bottom: 1px solid transparent;
}
._eli3_settings_creds_head ._eli3_settings_creds_title { flex: 0 1 auto; }
._eli3_settings_creds_head ._eli3_settings_creds_status { margin-left: 4px; }
._eli3_settings_creds_caret { font: 700 9px/1 'Inter', sans-serif; color: #475569; width: 10px; }
._eli3_settings_creds_title {
  font: 800 11px/1 'Inter', sans-serif; text-transform: uppercase;
  letter-spacing: 0.5px; color: #0f172a; flex: 1;
}
._eli3_settings_creds_status {
  font: 700 10px/1 'Inter', sans-serif; color: #64748b;
  background: #e2e8f0; padding: 3px 8px;
}
._eli3_settings_creds_body { padding: 8px 10px; border-top: 1px solid #e2e8f0; }
._eli3_settings_cred_import { width: 100%; margin-bottom: 8px; }
._eli3_settings_cred_row { padding-bottom: 6px; margin-bottom: 6px; border-bottom: 1px dashed #e2e8f0; }
._eli3_settings_cred_row:last-child { border-bottom: none; margin-bottom: 0; padding-bottom: 0; }
._eli3_settings_cred_label {
  font: 700 10px/1.2 'Inter', sans-serif; text-transform: uppercase;
  letter-spacing: 0.4px; margin-bottom: 3px; text-align: center;
}
._eli3_settings_cred_line { display: flex; gap: 4px; align-items: center; justify-content: center; }
._eli3_settings_cred_input { flex: 1; font: 11px 'JetBrains Mono', monospace; padding: 5px 8px; }
._eli3_settings_cred_eye {
  background: #f8fafc; border: 1px solid #cbd5e1; cursor: pointer;
  padding: 4px 8px; font-size: 14px; line-height: 1;
  color: #475569;
}
._eli3_settings_cred_eye:hover { background: #e2e8f0; color: #0f172a; }
._eli3_settings_cred_save { padding: 5px 10px !important; font-size: 11px !important; }

